import{b as p,j as e,db as de,ex as b,ey as E,ez as x,eA as $,eB as S,X as T,bs as A,bt as j,bu as l,eC as w,eD as _,eE as i,eF as N,bz as g,bA as O,bB as k,eG as R,bC as le,bD as C,bE as m,bF as P,eH as D,bG as c,eI as M,bH as q,bJ as me,bI as H,bK as B,eJ as I,eK as U,eL as L,eM as F,eN as G,eO as u,bx as z,eP as Y,bv as V,bw as W,bL as h,eQ as X,eR as Q,eS as K,eT as J,eU as s,eV as Z,M as ce,I as ue,bM as he}from"./index-fRA17t0_.js";import{r as pe}from"./vendor-sonner-BFkWhx6y.js";import{e as ge}from"./SoulFragmentTerm-Bg_ZFFS2.js";import{A as ee}from"./arenaUltimoAdversario-Cc9Mi5K5.js";import{g as ae}from"./guildCopy-CxR4eRTY.js";import"./vendor-DDxydHEc.js";import"./vendor-capacitor-BLfbYhNv.js";function Se({isOpen:oe,onClose:se,language:d="en-US"}){const te=d==="pt-BR",a=(n,r)=>te?n:r,[ne,re]=pe.useState(null),t=de,[,,y]=le,f=Math.round(he*g),v=me.length,o={...p,margin:0},ie=[{id:"evolve",title:a("Como seu Soulmon evolui","How it evolves"),body:e.jsxs(e.Fragment,{children:[e.jsx("p",{style:o,children:ge(a("Cada forma tem uma barra de Fragmentos de Alma. Todo hábito ou tarefa concluída rende fragmentos (tarefas maiores, 1 a 3), até a meta diária do estágio.","Each form has a Soul Fragment bar. Every habit or task you finish earns fragments (bigger tasks, 1 to 3), up to your stage’s daily goal."))}),e.jsx("p",{style:o,children:a("Eles entram na virada do dia e nunca diminuem; quando juntam o bastante, abrem a próxima forma.","They join at the turn of the day and never shrink; once you have enough, they open the next form.")}),e.jsx("p",{style:o,children:a(`Rookie→Champion pede ${t.rookie.gauge} passos (até ${t.rookie.required}/dia); Champion→Ultimate ${t.champion.gauge} (até ${t.champion.required}/dia); Ultimate→Mega ${t.ultimate.gauge} (até ${t.ultimate.required}/dia).`,`Rookie→Champion takes ${t.rookie.gauge} steps (up to ${t.rookie.required}/day); Champion→Ultimate ${t.champion.gauge} (up to ${t.champion.required}/day); Ultimate→Mega ${t.ultimate.gauge} (up to ${t.ultimate.required}/day).`)}),e.jsx("p",{style:o,children:a("Quem começa pela forma BB não tem meta diária: ela tem 6 corações, nada a desgasta (sem fome, sem cocô, sem perda no fim do dia) e evolui para Rookie quando o Vínculo chega ao nível 2. Enquanto é BB, Torneio, Duelo PvP e Guilda ficam fechados.","If you start as a BB, there is no daily goal: it has 6 hearts, nothing wears it down (no hunger, no poop, no end-of-day loss) and it evolves into a Rookie once your Bond reaches level 2. While it is a BB, the Tournament, PvP Duel and Guild stay closed.")}),e.jsx("p",{style:o,children:a(`Para chegar ao Ultra, primeiro libere as ${b.length} Megas (poder, harmonia e benevolência). Só depois disso a barra do Ultra começa a encher, e ela pede ${E} passos como mega.`,`To reach the Ultra, first unlock all ${b.length} Megas (power, harmony and benevolence). Only after that does the Ultra bar start filling, and it asks for ${E} steps as a mega.`)}),e.jsx("p",{style:o,children:a("Depois do Ultra existe o Renascimento, para quem tem a conta completa: sua criatura vira ovo, volta a Rookie e os atributos zeram.","After the Ultra comes Rebirth, for full accounts: your creature becomes an egg, returns to Rookie and attributes reset.")}),e.jsx("p",{style:o,children:a("Em troca ela nasce mais funda e você escolhe criatura, escola e elemento. Bits, cenários, sonhos, hábitos e o caminho andado ficam. Só acontece uma vez.","In exchange it is born deeper and you choose its creature, school and element. Bits, scenes, dreams, habits and the path walked stay. It happens only once.")}),e.jsx("p",{style:o,children:a("O caminho só acumula — um dia fraco soma pouco, nunca tira. Dia completo (a meta inteira) é um selo do dia: rende Bits, mas não faz evoluir.","The path only accumulates — a light day adds a little, never takes away. A complete day is a seal for the day: it pays Bits, but does not drive evolution.")}),e.jsx("p",{style:o,children:a("A evolução é sua: toque no Soulmon na página de Evolução para travar ou destravar o cadeado.","Evolution is yours: tap your Soulmon on the Evolution page to lock or unlock the padlock.")}),e.jsx("p",{style:o,children:a("Poção de elemento: no Centro de Evolução, gaste essências para preparar uma poção. Dê ao Soulmon pela pasta de itens e, na próxima evolução, ele carrega esse elemento. Vale só para a próxima evolução; depois o Soulmon volta ao elemento da pontuação dele. Outra poção substitui a que espera.","Element potion: at the Evolution Center, spend essences to brew a potion. Give it to your Soulmon from Files and, at the next evolution, it carries that element. Only affects the next evolution; after that your Soulmon returns to its score-based element. Another potion replaces the one waiting.")}),e.jsx("p",{style:o,children:a("Os pontos de Benevolência, Harmonia e Poder recomeçam do zero para a próxima forma.","Benevolence, Harmony and Power points start again from zero for the next form.")}),e.jsx("p",{style:o,children:a("Quando a barra enche, a próxima forma começa a tomar corpo e leva um tempo para ficar pronta. Volte quando quiser — ela espera, e nada se perde.","When the bar fills, the next form starts taking shape and takes a while to be ready. Come back whenever you like — it waits, and nothing is lost.")})]})},{id:"hearts",title:a("Corações","Hearts"),body:e.jsxs(e.Fragment,{children:[e.jsx("p",{style:o,children:a(`Na virada do dia você perde no máximo ${x} coração, proporcional ao que ficou por fazer. Cumpriu a meta, não perde nada.`,`At the day turn you lose at most ${x} heart, in proportion to what you left undone. Meet the goal and you lose nothing.`)}),e.jsx("p",{style:o,children:a(`Sumiu por ${$} dias ou mais? Voltar não custa nada. Toda segunda seu Soulmon recupera ${S} coração. O relatório diário diz qual pausa segurou o dia.`,`Away for ${$} days or more? Coming back costs nothing. Every Monday it recovers ${S} of a heart. The daily report says which pause held the day.`)}),e.jsx("p",{style:o,children:a("Cocô não limpo drena 1 coração a cada 6 horas — dê banho. Esfregar o pet cura (até 1 coração por dia). Se zerar, seu Soulmon regride uma forma.","Uncleaned poop drains 1 heart every 6 hours — give it a bath. Rubbing your pet is the main way to heal (up to 1 heart a day). At zero it degenerates one form.")})]})},{id:"care",title:a("Comida e energia","Food and energy"),body:e.jsxs(e.Fragment,{children:[e.jsx("p",{style:o,children:a(`As barras de energia são o dobro da meta diária do estágio (Rookie: ${T("rookie")}). Ela zera todo dia e não decide o dia completo.`,`Energy bars are twice your stage’s daily goal (Rookie: ${T("rookie")}). It resets daily and does not decide the complete day.`)}),e.jsx("p",{style:o,children:a(`Sobe com o tempo: 1 a cada ${A} min com o Soulmon bem alimentado, metade da velocidade com um pouco de fome, parada se ele estiver faminto. Dormindo, tudo isso ×${j} mais rápido (faminto continua parado).`,`It rises with time: 1 every ${A} min when your Soulmon is well fed, half speed when a little hungry, stopped when starving. While asleep, all of that runs ×${j} faster (starving stays stopped).`)}),e.jsx("p",{style:o,children:a(`Serve para descer a Masmorra: cada camada gasta ${l}, e subir de nível enche de novo.`,`It is what the Dungeon runs on: each layer spends ${l}, and leveling up refills it.`)}),e.jsx("p",{style:o,children:a(`Cada tarefa concluída rende uma comida. Alimentar enche a fome (cai do cheio ao vazio em ${w} h) e dá pontos de atributo, que definem o galho da evolução.`,`Each completed task yields one food. Feeding fills hunger (full to empty in ${w} h) and grants attribute points, which steer your evolution branch.`)}),e.jsx("p",{style:o,children:a(`NÃO dá energia direto e NÃO cura coração. Fome não custa nada além da energia parada. Até ${_} vezes por hora.`,`It does NOT give energy directly or heal hearts. Hunger costs nothing beyond paused energy. Up to ${_} times an hour.`)}),e.jsx("p",{style:o,children:a(`Depois do café, do almoço e do jantar (${i.breakfast}, ${i.lunch} e ${i.dinner}; muda nas Configurações), seu Soulmon pode pedir UMA coisa pequena por ${N/60} h: carinho, banho, comidinha.`,`After breakfast, lunch and dinner (${i.breakfast}, ${i.lunch} and ${i.dinner} — change them in Settings), your Soulmon may ask for ONE small thing for ${N/60} h: a pat, a rinse, a snack.`)}),e.jsx("p",{style:o,children:a("Não vale pontos, não conta e pular não custa nada. Os lembretes começam desligados.","It earns no points, nothing is counted, and skipping costs nothing. The reminders start off.")})]})},{id:"habits",title:a("Hábitos","Habits"),body:e.jsxs(e.Fragment,{children:[e.jsx("p",{style:o,children:a(`Não existe sequência que zera. O que aparece é a constância: "${f} das últimas ${g}". Uma falta custa uma fatia, nunca tudo.`,`There is no streak that resets. What you see is consistency: "${f} of the last ${g}". A missed day costs a slice, never everything.`)}),e.jsx("p",{style:o,children:a(`A cada ${O} dias de boa constância você ganha um escudo (até ${k}). Ele é gasto sozinho no dia em que você falta — nada para lembrar de ativar.`,`Every ${O} days of good consistency you earn a shield (up to ${k}). It is spent automatically on a day you miss — nothing to remember to switch on.`)}),e.jsx("p",{style:o,children:a(`Uma falta não gera nada. Em ${R} seguidas, o pet oferece uma versão bem menor do hábito — aceitar a torna a tarefa bônus do dia, que rende um ponto extra para a evolução.`,`One miss does nothing. At ${R} in a row, your pet offers a much smaller version of the habit — accepting makes it the day’s bonus task, worth one extra point toward evolution.`)}),e.jsx("p",{style:o,children:a(`E o ícone amadurece até virar árvore em ${y} dias feitos, rendendo mais atributo.`,`And the icon matures into a tree at ${y} days done, yielding more attribute.`)})]})},{id:"tasks",title:a("Tarefas","Tasks"),body:e.jsxs(e.Fragment,{children:[e.jsx("p",{style:o,children:a('Hábito acontece TODO DIA e aparece sempre no Hoje; tarefa é pontual ou em dias específicos e só aparece nos dias dela (a lista completa fica em "Ver tudo").','A habit happens EVERY DAY and always shows in Today; a task is one-off or on specific days and only shows on its days (the full list lives in "View all").')}),e.jsx("p",{style:o,children:a("Tarefa com subitens pesa pelo esforço escolhido, não pelo número deles. Cada subitem feito avança a barra e rende um pouco de XP (até 5, no máximo +50%).","A task with steps weighs by the effort you picked, not by its step count. Each finished step advances the bar and earns a little XP (up to 5, at most +50%).")}),e.jsx("p",{style:o,children:a("O peso nunca passa do que as mesmas tarefas soltas pesariam (máximo 3).","The weight never exceeds what the same loose tasks would (max 3).")}),e.jsx("p",{style:o,children:a("Fechar TODOS os subitens de tarefa com 3+ rende comida premium (★): 5 de energia em vez de 1, no máximo uma por dia e três por semana, dentro do teto do dia.","Finishing ALL steps of a task with 3 or more earns a premium food (★): 5 energy instead of 1, at most one a day and three a week, never above the day's max.")}),e.jsx("p",{style:o,children:a('O check de um hábito vale só para hoje; o "N de M" ao lado é só o resumo da semana.',`A habit's check counts only for that day; the "N of M" beside it is just the week's summary.`)}),e.jsx("p",{style:o,children:a("Toda tarefa tem um esforço: Rápida (1), Média (2) ou Projeto (3). A meta soma esforço, não itens — um Projeto vale três Rápidas.","Every task has an effort: Quick (1), Medium (2) or Project (3). The goal adds up effort, not items — one Project is worth three Quick ones.")}),e.jsx("p",{style:o,children:a(`Passando de ${C} pontos no dia, o pet avisa. É aviso, nunca bloqueio.`,`Past ${C} points in a day your pet says so. A heads-up, never a block.`)}),e.jsx("p",{style:o,children:a(`No check-in você escolhe até ${m} focos do dia; completar os ${m} rende o selo.`,`At check-in you pick up to ${m} focus tasks; completing all ${m} earns the seal.`)}),e.jsx("p",{style:o,children:a(`Parada há ${P} dias ela fica assombrada — e concluir uma assombrada dá bônus de alívio. Adiada ${D} vezes, o pet oferece dividir, encolher ou deixar pra lá.`,`Untouched for ${P} days it becomes haunted — clearing a haunted task grants a relief bonus. Postponed ${D} times, your pet offers to split, shrink or drop it.`)}),e.jsx("p",{style:o,children:a('"Algum dia" é permissão formal para não fazer agora: não conta na meta e não assombra. "Deixar pra lá" é um fim honesto, com volta atrás.',`"Someday" is formal permission not to do it now: it doesn't count toward the goal and never haunts. "Let it go" is an honest ending, with an undo.`)})]})},{id:"rest",title:a("Descanso e sonhos","Rest and dreams"),body:e.jsxs(e.Fragment,{children:[e.jsx("p",{style:o,children:a(`Você escolhe a SUA janela de sono (padrão ${c.start}–${c.end}, com ${M} min de tolerância). O que conta é o gesto de deitar no horário — nunca a qualidade do seu sono.`,`You choose YOUR own sleep window (default ${c.start}–${c.end}, with ${M} min of grace). What counts is going to bed on time — never how well you slept.`)}),e.jsx("p",{style:o,children:a(`Sem nota de sono e sem castigo: noite sem registro é neutra. A leitura é quantas das últimas ${q} noites entraram na janela.`,`No sleep score and no penalty: an unlogged night is neutral. The reading is how many of the last ${q} nights landed inside the window.`)}),e.jsx("p",{style:o,children:a(`Cada noite na janela seu Soulmon SONHA: uma cena colecionável dele — ${v} para descobrir. A raridade vem da regularidade, nunca de dormir mais.`,`Every night inside the window it DREAMS: a collectible scene of itself — ${v} to discover. Rarity comes from regularity, never from sleeping longer.`)}),e.jsx("p",{style:o,children:a(`Uma noite no horário também traz ${H} de energia a mais de manhã, uma vez por dia; sem noite, nada se perde.`,`A night on time also brings ${H} extra energy in the morning, once a day; no night, nothing is lost.`)})]})},{id:"passeio",title:a("Passeio e Travessias","Stroll and Crossings"),body:e.jsxs(e.Fragment,{children:[e.jsx("p",{style:o,children:a("Na Exploração fica o Passeio: seu Soulmon sai todo dia e conta o que viu no relatório do fim do dia. Você escolhe para onde — casa ou uma região já aberta.","The Stroll lives in Exploration: your Soulmon heads out daily and tells you what it saw in the end-of-day report. You pick where: home, or an open region.")}),e.jsx("p",{style:o,children:a("Travessias são opcionais: algo que você faz fora do app, com uma versão pequena para fazer em casa. Esperam o tempo que for; deixar pra lá não custa nada.","Crossings are optional: something you do outside the app, with a small version you can do at home. They wait as long as you like; letting one go costs nothing.")}),e.jsx("p",{style:o,children:a('O passeio fica com o NPC da Exploração: é lá que você escolhe. Escolhida, a tarefa "Passeio" aparece na Home; faça o passeio e marque (na Home ou de volta no NPC) para ver a cena na hora.','The stroll stays with the NPC in Exploration: that is where you pick. Once picked, the "Stroll" task shows on Home; do the stroll and mark it (on Home or back at the NPC) to see the scene right away.')}),e.jsx("p",{style:o,children:a('No menu de Missões fica a linha "Passeio" com o nome do passeio que você escolheu. Marcar ali ou no NPC dá no mesmo: a cena e as recompensas vêm na hora, uma vez só.','The Missions menu keeps a "Stroll" line with the stroll you picked. Marking it there or at the NPC is the same: the scene and rewards come right away, once.')}),e.jsx("p",{style:o,children:a("Há dois acessos na Home: missões diárias e semanais. Quando você conclui o passeio, a névoa de uma região se abre na hora.","Home has two doors: daily and weekly missions. Once you claim, the mist over a region clears on the next night's stroll.")}),e.jsx("p",{style:o,children:a("Nada disso mexe no seu Soulmon, na meta do dia, nos corações ou na evolução. E dá para esconder as Travessias na própria folha do Passeio.","None of it touches your Soulmon, the daily goal, hearts or evolution. You can also hide Crossings from the Stroll sheet itself.")})]})},{id:"guild",title:ae(d,"guild.guide.titulo"),body:e.jsx("p",{style:o,children:ae(d,"guild.guide.corpo")})},{id:"demo",title:a("A demo","The demo"),body:e.jsxs(e.Fragment,{children:[e.jsx("p",{style:o,children:a(`O botão DEMO abre o jogo sem conta, com um dos cinco Soulmon iniciais no Vínculo nível ${B}. A demo salva só neste aparelho e não faz compras.`,`The DEMO button opens the game without an account, with one of the five starter Soulmon at Bond level ${B}. The demo saves on this device only; no purchases.`)}),e.jsx("p",{style:o,children:a("Não ganha XP (o Vínculo fica fixo) e não entra no PvP (Torneio, Duelo, Drive e Clã ficam fechados). Para ter uma conta, saia da demo em Configurações.","It earns no XP (Bond stays fixed) and does not enter PvP (Tournament, Duel, Drive and Clan stay closed). To get an account, leave the demo in Settings.")})]})},{id:"more",title:a("O resto, em uma linha cada","Everything else, one line each"),body:e.jsxs(e.Fragment,{children:[e.jsx("p",{style:o,children:a("Galhos: Poder, Harmonia e Benevolência — os requisitos são iguais nos três. No empate decide o seu ritmo de cuidado, e nenhum ritmo é melhor.","Branches: Power, Harmony and Benevolence — requirements are identical across all three. Ties are decided by your care rhythm, and no rhythm is better.")}),e.jsx("p",{style:o,children:a("Traço de nascimento: todo Soulmon nasce com um (veja em Estatísticas). Todos são positivos.","Birth trait: every Soulmon is born with one (see it in Stats). All of them are upsides.")}),e.jsx("p",{style:o,children:a("A Fenda e o Torneio nunca cobram corações. Perder custa só a descida.","The Endless Rift and the Tournament never cost hearts. Losing only costs the descent.")}),e.jsx("p",{style:o,children:a(`A Masmorra é uma descida automática: a cada ${I} lutas você desce uma camada, até a ${U}. Cada camada gasta ${l} de energia.`,`The Dungeon is an automatic descent: every ${I} fights you go down a layer, up to ${U}. Each layer spends ${l} energy.`)}),e.jsx("p",{style:o,children:a(`A descida não tem limite por dia nem teto de profundidade: ela para quando a energia ou o HP acabam, sem custo nenhum. A energia é o freio do Rift. O HP volta com o tempo (uns ${L} h, até com o app fechado); descer de novo pede ${F}%.`,`The descent has no daily limit and no depth cap: it stops when energy or HP runs out, at no cost. Energy is the Rift's brake. HP returns over time (about ${L} h, even app closed); descending again needs ${F}%.`)}),e.jsx("p",{style:o,children:a(`A próxima descida recomeça no andar onde você parou, no combate 1 dele: perder nunca faz voltar de andar, só reinicia os combates do andar atual (ex.: venceu os 6 combates do andar 1 de um elemento e caiu no andar 2? Volta ao combate 1 do andar 2). A cada ${G} camadas há um marco, com 1% de chance de render o item 🌀, no máximo um por semana (veja Itens).`,`The next descent resumes at the layer where you stopped, at its fight 1: losing never sends you back a layer, it only restarts the fights of the current layer (e.g. you cleared all 6 fights of an element's layer 1 and fell on layer 2? You go back to fight 1 of layer 2). Every ${G} layers is a milestone with a 1% chance to earn the 🌀 item, at most one a week (see Items).`)}),e.jsx("p",{style:o,children:a("A Masmorra desce em conjuntos de 2 camadas, cada um de um elemento: do elemento puro aos combinados, e quanto mais elementos, mais evoluídos os inimigos. A última luta do conjunto é um mini-boss. Quanto mais fundo, mais difícil; às vezes o Soulmon não passa, e faz parte do desafio.","The Dungeon goes down in sets of 2 layers, each of one element: from single elements to combined ones, and the more elements, the more evolved the foes. The last fight of a set is a mini-boss. The deeper, the harder; sometimes your Soulmon cannot get past, and that is part of the challenge.")}),e.jsx("p",{style:o,children:a("Quanto mais Lv, mais fundo ele chega; uma profundidade nova (5, 10, 25, 50…) rende fragmentos do Soulsmith. Subir de nível enche energia e HP.","The higher your Soulmon's Lv, the deeper it reaches; a new depth (5, 10, 25, 50…) earns Soulsmith fragments. Leveling up refills energy and HP.")}),e.jsx("p",{style:o,children:a(`O Torneio é RANQUEADO e o servidor sorteia seus oponentes. Na Arena livre VOCÊ escolhe contra quem lutar, 1 de ${u} desafios, em ${z} rodadas, e o último adversário deixa ${ee}× a essência dele; sortear ${u} novos custa Bits depois de ${Y} grátis por dia. A aba Treino do Torneio é amistosa: não muda a sua posição. Todo dia você ganha 1 ticket grátis com 20 partidas com Honra (de 1 a 2 por vitória, até 20 de Honra por dia); para jogar mais, o ticket extra custa 30 Bits e dá +20 partidas sem Honra (até 3 por dia). Sortear outros oponentes lá é de graça e sem limite.`,`The Tournament is RANKED and the server draws your opponents. In the Open Arena YOU choose who to fight, 1 of ${u} challenges, over ${z} rounds, and the last opponent drops ${ee}× its essence; drawing ${u} new ones costs Bits after ${Y} free a day. The Tournament's Sparring tab is friendly: it never changes your rank. Every day you get 1 free ticket with 20 matches with Honor (1 to 2 per win, up to 20 Honor a day); to play more, an extra ticket costs 30 Bits and gives +20 matches without Honor (up to 3 a day). Drawing new opponents there is free and unlimited.`)}),e.jsx("p",{style:o,children:a("Nos duelos os pets lutam sozinhos. Toque em qualquer lugar para torcer: o gauge cheio vira um golpe especial. Torcer só ajuda; não torcer não atrapalha.","In duels the pets fight on their own. Tap anywhere to cheer: a full gauge becomes a special strike. Cheering only helps; skipping never hurts.")}),e.jsx("p",{style:o,children:a('Elementos contam na Arena, no Combina 3 e na Guerra de Guildas (metade do efeito; não nos Duelos do Torneio). Elemento que contra-ataca: um golpe a menos ("Super eficiente!"); o inverso, um a mais. Sem elemento, nada muda.','Elements count in the Arena, Combine 3 and the Guild War (half effect there; not Tournament Duels). A countering element lands one hit sooner ("Super effective!"); the reverse takes one more. No element, no change.')}),e.jsx("p",{style:o,children:a(`Vínculo N é o seu nível como pessoa que cuida: cada Vínculo (até ${V}) rende um ponto de talento, e nenhum dinheiro compra Vínculo.`,`Bond N is your own level as a carer: each Bond (up to ${V}) gives one talent point, and no money buys Bond.`)}),e.jsx("p",{style:o,children:a(`Só a Ranqueada do Torneio pede Vínculo ${W.ranqueada.minBond}; o resto é livre. Lv N é o do seu Soulmon.`,`Only the Tournament's Ranked mode asks for Bond ${W.ranqueada.minBond}; everything else is open. Lv N is your Soulmon's.`)}),e.jsx("p",{style:o,children:a(`Talentos e equipamento somam, no máximo, ${Math.round(h*100)}% de força em qualquer luta.`,`Talents and equipment add at most ${Math.round(h*100)}% strength in any fight.`)}),e.jsx("p",{style:o,children:a(`Cada peça chega no nível 1 pela missão de um prédio e se aprimora no Soulsmith até o nível ${X}, com os materiais das missões.`,`Each piece arrives at level 1 through a building mission and is upgraded at the Soulsmith up to level ${X}, with the materials missions give.`)}),e.jsx("p",{style:o,children:a(`Cada aprimoramento custa materiais e Bits (de ${Q(1)} no começo, crescendo a cada nível). A cada nível você escolhe entre dois ganhos (refazer custa ${K} Bits). Uma peça no máximo vale ${(J*100).toFixed(1).replace(".",",")}%.`,`Each upgrade costs materials and Bits (from ${Q(1)} at the start, growing each level). At each level you choose between two gains (redoing a choice costs ${K} Bits). One piece at the top is worth ${(J*100).toFixed(1)}%.`)}),e.jsx("p",{style:o,children:a(`Na Forja, a Hexsmith reescreve o código hex do Soulmon em cinco Portas, cada uma com o seu HEX: Coroa (família do especial), Amuleto (elemento do especial), Garra (elemento do ataque básico), Couraça (elemento na defesa, só o dano recebido) e Luvas (tipo do ataque básico: Magia, Corte à distância, Corte corpo a corpo ou Esmagamento; só visual). Os HEXes de elemento pedem ${s.element.potions} poções do próprio elemento + ${s.element.fragments} fragmentos + ${s.element.bits} Bits; a Coroa, ${s.coroa.fragments} fragmentos + ${s.coroa.bits} Bits; as Luvas, ${s.luvas.fragments} fragmentos + ${s.luvas.bits} Bits. Os HEXes ficam para sempre (não se vendem), um equipado por Porta, e trocar não perde o anterior.`,`At the Forge, the Hexsmith rewrites your Soulmon's hex code in five Ports, each holding its HEX: Crown (special family), Amulet (special element), Claw (basic attack element), Cuirass (element when defending, only damage taken) and Gloves (basic attack type: Magic, Ranged Slash, Melee Slash or Melee Smash; looks only). Element HEXes take ${s.element.potions} potions of that element + ${s.element.fragments} fragments + ${s.element.bits} Bits; the Crown, ${s.coroa.fragments} fragments + ${s.coroa.bits} Bits; the Gloves, ${s.luvas.fragments} fragments + ${s.luvas.bits} Bits. HEXes are kept forever (they can't be sold), one equipped per Port, and swapping never loses the previous one.`)}),e.jsx("p",{style:o,children:a(`As peças são partes da sua alma, aprimoradas: não há como tirar. Sem sorteio. Bits comprados com Créditos (até ${Z.toLocaleString("pt-BR")} Bits por dia em pacotes, no Cambista) também pagam o Soulsmith e a Hexsmith; o bônus de combate de todas as fontes juntas continua parando em ${Math.round(h*100)}%.`,`The pieces are parts of your soul, refined: nothing to take off. No draws. Bits bought with Credits (up to ${Z.toLocaleString("en-US")} Bits a day in packs, at the Exchanger) also pay the Soulsmith and the Hexsmith; the combat bonus from all sources together still stops at ${Math.round(h*100)}%.`)}),e.jsx("p",{style:o,children:a("O check-in e o relatório do dia levam vinte segundos; o de domingo descreve a semana. Nada disso vira nota.","Check-in and the daily report take twenty seconds; Sunday describes the week. None of it becomes a score.")}),e.jsx("p",{style:o,children:a("Toda segunda e todo dia 1 vem um recomeço: zera as cobranças pendentes e não apaga nada do que você conquistou.","Every Monday and every 1st a fresh start is offered: pending nagging is cleared and nothing you earned is erased.")})]})}];return e.jsxs(ce,{open:oe,onClose:se,language:d,title:a("Guia","Guide"),maxWidth:520,children:[e.jsx("p",{style:p,children:a("Toque num assunto. Nada aqui é obrigatório saber para jogar.","Tap a topic. None of this is required knowledge to play.")}),e.jsx("div",{style:{display:"flex",flexDirection:"column"},children:ie.map(n=>{const r=ne===n.id;return e.jsxs("div",{children:[e.jsxs("button",{type:"button",onClick:()=>re(r?null:n.id),"aria-expanded":r,"aria-controls":`guide-${n.id}`,className:"sm2-conta-chap",children:[e.jsx("span",{style:{flex:1,minWidth:0},children:n.title}),e.jsx(ue,{name:r?"expand_less":"expand_more",size:24,tone:r?"primary":"muted"})]}),r&&e.jsx("div",{id:`guide-${n.id}`,className:"sm2-conta-chapbody",children:n.body})]},n.id)})}),e.jsx("p",{style:p,children:a("Nos dias em que não der, seu Soulmon continua aqui.","On the days you can’t, it stays right here.")})]})}export{Se as GuideModal};
